diff --git a/packages/coding-agent/bench/fixtures/governor-compact-notes-v1/src/labels.ts b/packages/coding-agent/bench/fixtures/governor-compact-notes-v1/src/labels.ts
index 99c889c..8ed4b06 100644
--- a/packages/coding-agent/bench/fixtures/governor-compact-notes-v1/src/labels.ts
+++ b/packages/coding-agent/bench/fixtures/governor-compact-notes-v1/src/labels.ts
@@ -1,3 +1,14 @@
 export function normalizeLabels(labels: readonly string[]): string[] {
-	return labels.map(label => label.toLowerCase());
+	const normalized: string[] = [];
+	const seen = new Set<string>();
+
+	for (const label of labels) {
+		const value = label.trim().toLowerCase();
+		if (value && !seen.has(value)) {
+			seen.add(value);
+			normalized.push(value);
+		}
+	}
+
+	return normalized;
 }
